package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.component;
import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.DisplayName;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.ContractNodeSpec;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.ImplementationState;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.resource.ResourceOperationSpec;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill.ConditionExpr;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill.TriggerSpec;
public final class ResourceFlowComponentSpec extends ContractNodeSpec{public static final String VARIANT="RESOURCE_FLOW";private final TriggerSpec trigger;private final ConditionExpr condition;private final ResourceOperationSpec operation;public ResourceFlowComponentSpec(StableId id,DisplayName name,TriggerSpec trigger,ConditionExpr condition,ResourceOperationSpec operation){super(id,name,NodeKind.COMPONENT,VARIANT,ImplementationState.IMPLEMENTED);if(trigger==null||condition==null||operation==null)throw new IllegalArgumentException("resource flow fields required");this.trigger=trigger;this.condition=condition;this.operation=operation;}public TriggerSpec trigger(){return trigger;}public ConditionExpr condition(){return condition;}public ResourceOperationSpec operation(){return operation;}@Override public ResourceFlowComponentSpec withIdentity(StableId id){return new ResourceFlowComponentSpec(id,displayName(),trigger,condition,operation);}@Override public ResourceFlowComponentSpec withDisplayName(DisplayName name){return new ResourceFlowComponentSpec(id(),name,trigger,condition,operation);}}
